/// Unescape PS3 OHS v2 encoded data.
/// The PS3 OHS client escapes & -> &a and % -> &m before sending.
pub fn unescape(s: &str) -> String {
    s.replace("&m", "%").replace("&a", "&")
}

/// Escape a string for PS3 OHS v2 (& -> &a, % -> &m).
pub fn escape(s: &str) -> String {
    s.replace('&', "&a").replace('%', "&m")
}

/// Decrypt a PS3 OHS v2 payload.
/// The first two bytes encode the cipher offset:
///   offsethi = byte[0] - 32
///   offsetlo = byte[1] - 32
///   offset   = offsethi * 95 + offsetlo + 1   (1-based, as in Lua)
/// Remaining bytes are XOR-decrypted via the cipher table.
/// Returns None if the input is too short or contains out-of-range bytes.
pub fn decrypt(data: &str) -> Option<String> {
    let bytes = data.as_bytes();
    if bytes.len() < 2 {
        return None;
    }

    let b0 = bytes[0] as i64;
    let b1 = bytes[1] as i64;
    if b0 < 32 || b1 < 32 {
        return None;
    }

    let offsethi = b0 - 32;
    let offsetlo = b1 - 32;
    let offset = (offsethi * 95 + offsetlo + 1) as usize; // 1-based offset

    let len = CIPHER.len();
    let mut result = Vec::with_capacity(bytes.len() - 2);

    for (k, &byte) in bytes[2..].iter().enumerate() {
        let srcbyte = byte as i64 - 32;
        // Lua: cipher[wrapped((i-2) + offset, #cipher)] where i goes 3..#str
        // i-2 for i=3 is 1, so for k-th element (0-indexed): k+1 (1-indexed position)
        // cipher index (0-indexed) = ((k + 1 + offset - 1) % len) = (k + offset) % len
        let cipher_index = (k + offset) % len;
        let cipherbyte = CIPHER[cipher_index] as i64;
        let decbyte = ((srcbyte - cipherbyte).rem_euclid(95) + 32) as u8;
        result.push(decbyte);
    }

    String::from_utf8(result).ok()
}

/// Encrypt a string for PS3 OHS v2 response.
/// A random offset (1..=9025) is chosen, encoded in the first two bytes,
/// then each character is cipher-encrypted.
pub fn encrypt(data: &str, offset: usize) -> Option<String> {
    assert!(offset >= 1 && offset <= 95 * 95, "offset out of range");

    let bytes = data.as_bytes();
    let len = CIPHER.len();

    let off = offset - 1; // 0-based
    let offsethi = off / 95;
    let offsetlo = off % 95;

    let mut result = Vec::with_capacity(bytes.len() + 2);
    result.push((offsethi as u8) + 32);
    result.push((offsetlo as u8) + 32);

    for (k, &byte) in bytes.iter().enumerate() {
        let srcbyte = byte as i64 - 32;
        // cipher index (0-indexed) = (k + offset) % len  (offset is 1-based)
        let cipher_index = (k + offset) % len;
        let cipherbyte = CIPHER[cipher_index] as i64;
        let encbyte = ((srcbyte + cipherbyte).rem_euclid(95) + 32) as u8;
        result.push(encbyte);
    }

    String::from_utf8(result).ok()
}

/// Encrypt data, iterating offsets 1..=9025 until the output contains no
/// XML-unsafe bytes (`<` 60, `>` 62, `&` 38) — including the 2-byte offset
/// header. This lets the result be embedded directly in `<ohs>...</ohs>`
/// without XML entity-encoding, which the PS3's FpXml does NOT reverse before
/// passing the text to decrypt().
///
/// For short payloads (~12 bytes) roughly 67% of offsets are safe, so this
/// typically resolves within 1–2 iterations.
pub fn encrypt_xml_safe(data: &str) -> Option<String> {
    for offset in 1..=(95 * 95) {
        if let Some(enc) = encrypt(data, offset) {
            if enc.bytes().all(|b| b != b'<' && b != b'>' && b != b'&') {
                return Some(enc);
            }
        }
    }
    None // exhausted all offsets — should never happen in practice
}
